            return min(budget, target)
        target = 62.0
        if bob_bid is not None:
            target = max(target, bob_bid + 1.5)
        return min(budget, target)

    if eric_bid is not None and eric_bid >= 95:
        if scarcity:
            target = 41.0 if hp > 6 and no_water_days == 0 else 74.0
        else:
            target = 34.0
        return min(budget, target)

    if bob_bid is not None:
        if 50.0 <= bob_bid <= 75.0:
            target = bob_bid + 1.5 if scarcity else bob_bid + 0.5
