def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    # Extract yesterday's bids from alive opponents
    prev_bids = []
    for opp in alive_opponents:
        trace = opp.get('previous_trace', {})
        if trace and trace.get('bid') is not None:
            prev_bids.append(trace['bid'])

    supply = day_context['supply']
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    # Base bid: if we are desperate (hp <= 2 or no_water_days >= 2), bid high
    if hp <= 2 or no_water_days >= 2:
        # Need to outbid the likely max from yesterday
        if prev_bids:
            max_prev = max(prev_bids)
            target = max_prev + 1.0
        else:
            target = DAILY_SALARY * 0.85
        return min(budget, max(target, DAILY_SALARY * 0.7))

    # If we are healthy, try to save budget
    if hp > 5:
        # If supply is high (>=20), we can survive with low bid
        if supply >= 20:
            return min(budget, DAILY_SALARY * 0.3)
        else:
            return min(budget, DAILY_SALARY * 0.45)

    # Moderate health: bid around 0.5 salary or slightly above previous low
    if prev_bids:
        min_prev = min(prev_bids)
        # If previous min bid is low, undercut?
        if min_prev < DAILY_SALARY * 0.5:
            return min(budget, min_prev + 1.0)
        else:
            return min(budget, DAILY_SALARY * 0.55)
    return min(budget, DAILY_SALARY * 0.5)

