def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # If no opponents, bid very low to save budget.
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.2)

    # Collect yesterday's bids from active opponents
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    highest_prev_bid = 0
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

    # Determine scarcity
    num_water_slots = int(day_context['supply'] // WATER_REQ)
    num_contenders = len(alive_opponents) + 1 # Including myself

    # Base bid strategy
    if num_water_slots < num_contenders: # Supply is scarce, high competition expected
        if my_status['hp'] <= 3: # Critical HP
            # Bid very aggressively to survive
            return min(my_status['budget'], DAILY_SALARY * 0.95)
        elif my_status['hp'] <= 6: # Low HP
            # Bid high, but leave some buffer, reacting to high previous bids
            return min(my_status['budget'], max(DAILY_SALARY * 0.8, highest_prev_bid + 5))
        else: # Healthy HP
            # Bid above previous high, but not desperate
            return min(my_status['budget'], max(DAILY_SALARY * 0.6, highest_prev_bid + 3))
    else: # Supply is sufficient or abundant
        if my_status['hp'] <= 3: # Critical HP, even with abundant supply, secure water
            return min(my_status['budget'], DAILY_SALARY * 0.8)
        elif my_status['hp'] <= 6: # Low HP
            # Bid moderately high to secure water, reacting to reasonable previous bids
            bid_val = DAILY_SALARY * 0.55
            if highest_prev_bid > 0 and highest_prev_bid < DAILY_SALARY * 0.7:
                bid_val = max(bid_val, highest_prev_bid + 1)
            return min(my_status['budget'], bid_val)
        else: # Healthy HP
            # Bid cautiously. If previous bids were low, bid base. Don't overreact to very high bids.
            bid_val = DAILY_SALARY * 0.4
            if highest_prev_bid > 0 and highest_prev_bid < DAILY_SALARY * 0.6:
                bid_val = max(bid_val, highest_prev_bid + 1)
            return min(my_status['budget'], bid_val)

    # Fallback in case none of the above conditions are met (should not happen)
    return min(my_status['budget'], DAILY_SALARY * 0.5)
